      , MAX(cm_6_cte.returns_on_order_date) AS returns_on_order_date
      , MAX(subq_20.orders_total) AS orders_total
    FROM cm_6_cte
    FULL OUTER JOIN (
      -- Aggregate Inputs for Simple Metrics
      -- Compute Metrics via Expressions
      SELECT
        metric_time__week
        , SUM(__orders_total) AS orders_total
      FROM (
        -- Read Elements From Semantic Model 'orders'
        -- Metric Time Dimension 'order_date'
        -- Select: ['__orders_total', 'metric_time__week']
        -- Select: ['__orders_total', 'metric_time__week']
        SELECT
          TIMESTAMP_TRUNC(order_date, isoweek) AS metric_time__week
          , 1 AS __orders_total
        FROM {{ ref('slv_orders') }} orders_src_10000
      ) subq_18
      GROUP BY
        metric_time__week
    ) subq_20
    ON
      cm_6_cte.metric_time__week = subq_20.metric_time__week
    GROUP BY
      metric_time__week
  ) subq_21
  ON
    subq_12.metric_time__week = subq_21.metric_time__week
  GROUP BY
    metric_time__week
) as metricflow
union all
select
  'month' as grain,
  cast(metric_time__month as date) as period_start,
  'total' as slice,
  cast(null as string) as slice_value,
  damaged_return_share,
  return_rate
from (
  -- Combine Aggregated Outputs
  -- Write to DataTable
  WITH sma_10015_cte AS (
    -- Read Elements From Semantic Model 'returns'
    -- Metric Time Dimension 'order_date'
    SELECT
      TIMESTAMP_TRUNC(order_date, month) AS metric_time__month
      , reason AS return__reason
      , 1 AS __returns_on_order_date
    FROM {{ ref('slv_returns') }} returns_src_10000
  )

  , cm_6_cte AS (
    -- Read From CTE For node_id=sma_10015
    -- Select: ['__returns_on_order_date', 'metric_time__month']
    -- Select: ['__returns_on_order_date', 'metric_time__month']
    -- Aggregate Inputs for Simple Metrics
    -- Compute Metrics via Expressions
    SELECT
      metric_time__month
      , SUM(__returns_on_order_date) AS returns_on_order_date
    FROM sma_10015_cte
    GROUP BY
      metric_time__month
  )

  SELECT
    COALESCE(subq_12.metric_time__month, subq_21.metric_time__month) AS metric_time__month
    , MAX(CAST(subq_12.damaged_returns AS FLOAT64) / CAST(NULLIF(subq_12.returns_on_order_date, 0) AS FLOAT64)) AS damaged_return_share
    , MAX(CAST(subq_21.returns_on_order_date AS FLOAT64) / CAST(NULLIF(subq_21.orders_total, 0) AS FLOAT64)) AS return_rate
  FROM (
    -- Combine Aggregated Outputs
    SELECT
      COALESCE(subq_6.metric_time__month, cm_6_cte.metric_time__month) AS metric_time__month
      , MAX(subq_6.damaged_returns) AS damaged_returns
      , MAX(cm_6_cte.returns_on_order_date) AS returns_on_order_date
    FROM (
      -- Constrain Output with WHERE
      -- Select: ['__returns_on_order_date', 'metric_time__month']
      -- Aggregate Inputs for Simple Metrics
      -- Compute Metrics via Expressions
      SELECT
        metric_time__month
        , SUM(returns_on_order_date) AS damaged_returns
      FROM (
        -- Read From CTE For node_id=sma_10015
        -- Select: ['__returns_on_order_date', 'return__reason', 'metric_time__month']
        SELECT
          metric_time__month
          , return__reason
          , __returns_on_order_date AS returns_on_order_date
        FROM sma_10015_cte
      ) subq_2
      WHERE return__reason = 'damaged'
      GROUP BY
        metric_time__month
    ) subq_6
    FULL OUTER JOIN
      cm_6_cte
    ON
      subq_6.metric_time__month = cm_6_cte.metric_time__month
    GROUP BY
      metric_time__month
  ) subq_12
  FULL OUTER JOIN (
    -- Combine Aggregated Outputs
    SELECT
      COALESCE(cm_6_cte.metric_time__month, subq_20.metric_time__month) AS metric_time__month
      , MAX(cm_6_cte.returns_on_order_date) AS returns_on_order_date
      , MAX(subq_20.orders_total) AS orders_total
    FROM cm_6_cte
    FULL OUTER JOIN (
      -- Aggregate Inputs for Simple Metrics
      -- Compute Metrics via Expressions
      SELECT
        metric_time__month
        , SUM(__orders_total) AS orders_total
      FROM (
        -- Read Elements From Semantic Model 'orders'
        -- Metric Time Dimension 'order_date'
        -- Select: ['__orders_total', 'metric_time__month']
        -- Select: ['__orders_total', 'metric_time__month']
        SELECT
          TIMESTAMP_TRUNC(order_date, month) AS metric_time__month
          , 1 AS __orders_total
        FROM {{ ref('slv_orders') }} orders_src_10000
      ) subq_18
      GROUP BY
        metric_time__month
    ) subq_20
    ON
      cm_6_cte.metric_time__month = subq_20.metric_time__month
    GROUP BY
      metric_time__month
  ) subq_21
  ON
    subq_12.metric_time__month = subq_21.metric_time__month
  GROUP BY
    metric_time__month
) as metricflow
